{
  "schemaVersion": "versionless.angular-tiny-translator-green-lane.v1",
  "unit": "lrapr-t006/u17c-tiny-translator-green-parity",
  "consentId": "VL-LEGACY-CORPUS-2026-08-10",
  "result": "three-demand-families-answered-build-red-residual-itemised",
  "meaning": "The three demand families u17b itemised are answered by capabilities that read the installed closure and the compiler, not by edits this record does not name. The build went from 72 diagnostics and 29 unresolvable module specifiers to 4 diagnostics and 0 unresolvable specifiers, and it is still red. The four diagnostics that remain are demands no capability in this unit carried, and they are itemised below. No artifact was emitted, so no parity is claimed.",
  "supersedes": {
    "record": "u17b-migrated-lane.json",
    "unit": "lrapr-t006/u17b-tiny-translator-migrated-lane",
    "why": "u17b recorded the red build and itemised four demands. Three of them — the @angular/material barrel, the Node `util` core module in browser code, and the RxJS 5 prototype patching — are answered here, and the fourth (the NG2003/NG6001 injection-token errors) cleared with the barrel as u17b predicted it would. This record replaces the demand list with what the build says now."
  },
  "capabilities": [
    {
      "name": "barrel-entry-point-split",
      "package": "@versionless/angular",
      "answers": "the @angular/material barrel demand, and the injection-token demand that followed it",
      "mechanism": "The installed package's own exports map is enumerated, each entry point's declaration file is parsed, and every barrel symbol is mapped to the shallowest entry point whose surface carries it. A symbol on no surface is refused by name and its whole declaration is left alone. Nothing about @angular/material is written into the capability: the same reading of a package that kept its barrel reports nothing to split.",
      "applicationFilesChanged": 8
    },
    {
      "name": "node-core-binding-migration",
      "package": "@versionless/angular",
      "answers": "the application half of the `util` demand — 16 modules importing isNullOrUndefined, isString and format",
      "mechanism": "Each binding is expanded into the ECMAScript that Node documents it as: `isNullOrUndefined(x)` becomes `(x == null)`, `isString(x)` becomes `(typeof x === 'string')`, and every expansion mentions its argument exactly once so no call can be evaluated twice. `format` is expanded as a directive reading — a literal %s-only format string becomes a template literal — and refused for every other directive. A module with one reference the table cannot expand keeps its import and every call site.",
      "applicationFilesChanged": 16
    },
    {
      "name": "declared browser dependency for `util`",
      "package": "the application manifest",
      "answers": "the library half of the `util` demand — ngx-i18nsupport-lib 1.10.2's own `require('util')`",
      "mechanism": "No application transform reaches a published library's own imports, and no shim was authored for it. The workspace declares `util@^0.12.5` — the published browser implementation of the core module — as an explicit dependency, so ordinary node resolution answers the library's require and the declaration is visible in the manifest rather than hidden in a bundler alias. It is scoped to the specifier rather than to the dependency, because the browser builder exposes no issuer-scoped alias; the only importer left after the call-site transform is ngx-i18nsupport-lib, and that is a fact about this closure rather than a guarantee the mechanism enforces.",
      "applicationFilesChanged": 0
    },
    {
      "name": "rxjs-prototype-patch-migration",
      "package": "@versionless/angular",
      "answers": "the RxJS 5 prototype-patch demand — 37 call sites and 19 patch imports",
      "mechanism": "Which `.map(` belongs to an observable and which to an array is not a question the syntax answers, so the capability does not ask the syntax: it takes the compiler's TS2339 diagnostics, each naming a position and the receiver's type, and moves exactly those call sites. Instance operators become `pipe(...)` with the operator imported by name, static creation methods become the free functions of the installed root, and every name emitted is checked against the installed RxJS surface first. Refusal is per module and total, and the patch imports are dropped only where every call site the compiler named in that module moved.",
      "applicationFilesChanged": 12
    }
  ],
  "iteration": {
    "why": "A diagnostic-driven transform sees only what the compiler could still type. A `.map` whose receiver is the result of an already-failed `.catch` is typed `any` and produces no diagnostic, so it becomes visible only after the call before it is fixed. The lane is therefore a fixpoint, and the record says how many rounds it took rather than presenting the result as one pass.",
    "rounds": [
      {
        "round": 1,
        "diagnosticsRead": "build-1.stderr.log (the u17b build)",
        "moved": "rxjs: 10 files, 51 changes. barrel: 8 files, 8 declarations split. util: 16 files, 50 call sites and imports."
      },
      {
        "round": 2,
        "diagnosticsRead": "build-2.stderr.log",
        "moved": "rxjs: 2 files, 5 changes — the call sites that were typed `any` until round 1 fixed the call before them. The other two capabilities found nothing left to do, which is the check that they are idempotent."
      }
    ]
  },
  "acquisition": {
    "purpose": "Install the one dependency this lane declared: the published browser implementation of Node's `util`, for a library that imports it from its own published code.",
    "consentId": "VL-LEGACY-CORPUS-2026-08-10",
    "networkMode": "consented",
    "method": "npm install --no-audit --no-fund, in the applied tree, with the manifest declaring util@^0.12.5.",
    "outcome": "succeeded",
    "exitStatus": 0,
    "packagesAdded": 16,
    "hosts": [
      "registry.npmjs.org"
    ]
  },
  "builds": [
    {
      "name": "build-1",
      "exitStatus": 1,
      "diagnostics": 72,
      "unresolvedSpecifiers": 29,
      "diagnosticListSha256": "cfe0f7c74b2a57d5fb8c787eff86cf49fc217e6acfd70d5d5e924818b0115c40"
    },
