1	/**
2	 * The green lane of the `angular-tiny-translator-v0-12-0` cell: the four demand
3	 * families u17b itemised, answered by capabilities, and the production build run
4	 * again on the result.
5	 *
6	 * u17b recorded a red build and named every demand. This driver is what the list
7	 * was for. It reads the installed closure — @angular/material's own entry-point
8	 * surface and RxJS's own export surface — hands those readings to
9	 * `@versionless/angular`, and writes back whatever the capabilities produce.
10	 * Nothing in this file decides what a symbol maps to or what a call site becomes;
11	 * it decides only which tree is being rewritten and where the compiler's
12	 * diagnostics were read from.
13	 *
14	 * The RxJS transform is diagnostic-driven, and that makes the lane iterative by
15	 * construction: a `.map` on a receiver the compiler has already given up on is
16	 * typed `any` and produces no diagnostic, so it becomes visible only once the
17	 * call before it is fixed. Each round is a build, a diagnostic read, and an
18	 * application; the record names how many rounds it took and what each one moved.
19	 */
20	
21	import { readFile, readdir, writeFile } from 'node:fs/promises';
22	import * as path from 'pathe';
23	import {
24		migrateNodeCoreBindings,
25		migrateRxjsPrototypePatches,
26		readEntryPointSurface,
27		splitBarrelImports,
28		type EntryPointSurface,
29		type PackageSurfaceReading,
30		type PatchedCallDiagnostic,
31		type RxjsSurfaceReading,
32	} from '../../../frameworks/angular/src/index.ts';
33	import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-tiny-translator-apply-run.ts';
34	
35	/** The package whose barrel this application imports from. */
36	export const BARREL_PACKAGE = '@angular/material';
37	/** The Node core module this application's browser code reaches. */
38	export const CORE_SPECIFIER = 'util';
39	
40	type ExportsMap = Readonly<Record<string, unknown>>;
41	
42	function typesTarget(target: unknown): string | null {
43		if (typeof target === 'string') return target.endsWith('.d.ts') ? target : null;
44		if (typeof target !== 'object' || target === null) return null;
45		const map = target as Readonly<Record<string, unknown>>;
46		const types = map['types'];
47		if (typeof types === 'string') return types;
48		const fallback = map['default'];
49		return typeof fallback === 'string' && fallback.endsWith('.d.ts') ? fallback : null;
50	}
51	
52	/**
53	 * Every entry point an installed package publishes a declaration file for, read
54	 * from its own `exports` map. A subpath with a wildcard is skipped: it names a
55	 * family of files rather than an entry point, and nothing can be resolved into
56	 * it without inventing the star.
57	 */
58	export async function readPackageSurface(
59		tree: string,
60		name: string,
61	): Promise<PackageSurfaceReading> {
62		const directory = path.join(tree, 'node_modules', name);
63		const manifest: unknown = JSON.parse(await readFile(path.join(directory, 'package.json'), 'utf8'));
64		const record = manifest as Readonly<{ version?: unknown; exports?: unknown }>;
65		const exportsField = record.exports;
66		if (typeof exportsField !== 'object' || exportsField === null)
67			throw new Error(`${name} publishes no exports map, so its entry points cannot be enumerated`);
68		const entryPoints: EntryPointSurface[] = [];
69		for (const [subpath, target] of Object.entries(exportsField as ExportsMap)) {
70			if (subpath.includes('*')) continue;
71			const types = typesTarget(target);
72			if (types === null) continue;
73			const file = path.join(directory, types);
74			const declaration = await readFile(file, 'utf8').catch(() => null);
75			if (declaration === null) continue;
76			entryPoints.push(readEntryPointSurface(name, subpath, declaration));
77		}
78		return Object.freeze({
79			name,
80			version: typeof record.version === 'string' ? record.version : 'unknown',
81			entryPoints: Object.freeze(entryPoints),
82		});
83	}
84	
85	/** The installed RxJS root and pipeable-operator surfaces. */
86	export async function readRxjsSurface(tree: string): Promise<RxjsSurfaceReading> {
87		const surface = await readPackageSurface(tree, 'rxjs');
88		const entry = (subpath: string): readonly string[] =>
89			surface.entryPoints.find((candidate) => candidate.subpath === subpath)?.exports ?? [];
90		return Object.freeze({
91			version: surface.version,
92			rootExports: entry('.'),
93			operatorExports: entry('./operators'),
94		});
95	}
96	
97	/**
98	 * The patched call sites a TypeScript build named. Every `TS2339` diagnostic
99	 * carries the file, the 1-based position, the property and the receiver's type,
100	 * which is the whole of what the RxJS capability needs and more than any reading
101	 * of the syntax could supply.
102	 */
103	export function readPatchedCallDiagnostics(
104		log: string,
105	): ReadonlyMap<string, readonly PatchedCallDiagnostic[]> {
106		const found = new Map<string, PatchedCallDiagnostic[]>();
107		const pattern =
108			/(src\/[^\s():]+\.ts):(\d+):(\d+) - error TS2339: Property '([^']+)' does not exist on type '(.+)'\./g;
109		for (const match of log.matchAll(pattern)) {
110			const [, file, line, column, property, receiverType] = match;
111			if (
112				file === undefined ||
113				line === undefined ||
114				column === undefined ||
115				property === undefined ||
116				receiverType === undefined
117			)
118				continue;
119			const list = found.get(file) ?? [];
120			const diagnostic: PatchedCallDiagnostic = Object.freeze({
121				line: Number.parseInt(line, 10),
122				column: Number.parseInt(column, 10),
123				property,
124				receiverType,
125			});
126			if (!list.some((entry) => entry.line === diagnostic.line && entry.column === diagnostic.column))
127				list.push(diagnostic);
128			found.set(file, list);
129		}
130		return found;
131	}
132	
133	async function sourceFiles(root: string): Promise<readonly string[]> {
134		const found: string[] = [];
135		const walk = async (directory: string): Promise<void> => {
136			for (const entry of await readdir(directory, { withFileTypes: true })) {
137				const full = path.join(directory, entry.name);
138				if (entry.isDirectory()) await walk(full);
139				else if (entry.name.endsWith('.ts')) found.push(full);
140			}
141		};
142		await walk(root);
143		return Object.freeze(found.sort());
144	}
145	
146	export type CapabilityOutcome = Readonly<{
147		capability: string;
148		filesChanged: readonly string[];
149		changes: readonly string[];
150		declaredDifferences: readonly string[];
151		unhandled: readonly string[];
152	}>;
153	
154	/**
155	 * Apply one round of the three capabilities to the applied tree, and report what
156	 * each of them did and refused.
157	 *
158	 * The RxJS capability runs first, and the order is load-bearing: its input is a
159	 * set of compiler positions read from the build of exactly these bytes, and a
160	 * capability that removed an import line before it ran would move every line
161	 * below the removal out from under those positions. The other two resolve their
162	 * own sites from the parsed module and do not care when they run.
163	 */
164	export async function applyRound(
165		diagnosticsLog: string | null,
166	): Promise<readonly CapabilityOutcome[]> {
167		const root = path.join(APPLIED_TREE, 'src');
168		const files = await sourceFiles(root);
169		const relative = (file: string): string => path.relative(APPLIED_TREE, file);
170		const outcomes: CapabilityOutcome[] = [];
171	
172		if (diagnosticsLog !== null) {
173			const rxjs = await readRxjsSurface(APPLIED_TREE);
174			const diagnostics = readPatchedCallDiagnostics(await readFile(diagnosticsLog, 'utf8'));
175			const rxjsChanged: string[] = [];
176			const rxjsChanges: string[] = [];
177			const rxjsUnhandled: string[] = [];
178			for (const file of files) {
179				const name = relative(file);
180				const source = await readFile(file, 'utf8');
181				const migration = migrateRxjsPrototypePatches(
182					name,
183					source,
184					diagnostics.get(name) ?? [],
185					rxjs,
186				);
187				rxjsUnhandled.push(...migration.unhandled);
188				if (!migration.changed) continue;
189				await writeFile(file, migration.source);
190				rxjsChanged.push(name);
191				for (const change of migration.changes)
192					rxjsChanges.push(`${name} line ${String(change.line)}: ${change.from} → ${change.to}`);
193			}
194			outcomes.push({
195				capability: `rxjs-prototype-patch-migration (rxjs@${rxjs.version})`,
196				filesChanged: Object.freeze(rxjsChanged),
197				changes: Object.freeze(rxjsChanges),
198				declaredDifferences: Object.freeze([]),
199				unhandled: Object.freeze(rxjsUnhandled),
200			});
201		}
202		const barrel = await readPackageSurface(APPLIED_TREE, BARREL_PACKAGE);
203		const barrelChanged: string[] = [];
204		const barrelChanges: string[] = [];
205		const barrelUnhandled: string[] = [];
206		for (const file of files) {
207			const source = await readFile(file, 'utf8');
208			const migration = splitBarrelImports(relative(file), source, barrel);
209			barrelUnhandled.push(...migration.unhandled);
210			if (!migration.changed) continue;
211			await writeFile(file, migration.source);
212			barrelChanged.push(relative(file));
213			for (const change of migration.changes)
214				barrelChanges.push(
215					`${relative(file)} line ${String(change.line)}: ${change.symbols.join(', ')} → ${change.to}`,
216				);
217		}
218		outcomes.push({
219			capability: `barrel-entry-point-split (${BARREL_PACKAGE}@${barrel.version})`,
220			filesChanged: Object.freeze(barrelChanged),
221			changes: Object.freeze(barrelChanges),
222			declaredDifferences: Object.freeze([]),
223			unhandled: Object.freeze(barrelUnhandled),
224		});
225	
226		const coreChanged: string[] = [];
227		const coreChanges: string[] = [];
228		const coreDifferences: string[] = [];
229		const coreUnhandled: string[] = [];
230		for (const file of files) {
231			const source = await readFile(file, 'utf8');
232			const migration = migrateNodeCoreBindings(relative(file), source, CORE_SPECIFIER);
233			coreUnhandled.push(...migration.unhandled);
234			coreDifferences.push(...migration.declaredDifferences);
235			if (!migration.changed) continue;
236			await writeFile(file, migration.source);
237			coreChanged.push(relative(file));
238			for (const change of migration.changes)
239				coreChanges.push(`${relative(file)} line ${String(change.line)}: ${change.kind}`);
240		}
241		outcomes.push({
242			capability: `node-core-binding-migration ('${CORE_SPECIFIER}')`,
243			filesChanged: Object.freeze(coreChanged),
244			changes: Object.freeze(coreChanges),
245			declaredDifferences: Object.freeze(coreDifferences),
246			unhandled: Object.freeze(coreUnhandled),
247		});
248	
249		return Object.freeze(outcomes);
250	}
251	
252	export async function main(): Promise<void> {
253		const log = process.argv[2] ?? null;
254		const outcomes = await applyRound(log === null ? null : path.resolve(log));
255		await writeFile(
