257			`${JSON.stringify(outcomes, null, '\t')}\n`,
258		);
259		for (const outcome of outcomes)
260			process.stdout.write(
261				`${outcome.capability}: ${String(outcome.filesChanged.length)} files changed, ` +
262					`${String(outcome.changes.length)} changes, ${String(outcome.unhandled.length)} refused\n`,
263			);
264	}
