1	/**
2	 * Imports of a package barrel that the installed package no longer answers.
3	 *
4	 * A library that once published every symbol from its package root and later
5	 * moved to one secondary entry point per component leaves an application's
6	 * barrel import resolving to a package that exports almost nothing. The
7	 * diagnostic is not a missing package and not a renamed symbol: the symbols are
8	 * all still published, one directory deeper each, and the import has to be split
9	 * into the entry points that own them.
10	 *
11	 * The split is a reading of the installed closure, never a table:
12	 *
13	 * - the entry points are the subpaths the package's own `exports` map names,
14	 * - each entry point's surface is the set of names its published declaration
15	 *   file exports, parsed rather than assumed,
16	 * - a symbol is mapped only when exactly one entry point at the shallowest
17	 *   depth that carries it exports it, and
18	 * - a symbol no entry point exports is refused by name.
19	 *
20	 * Nothing here knows which library it is looking at. A package that kept its
21	 * barrel exports the symbols from the root entry point, the root wins, and this
22	 * capability reports that there is nothing to split.
23	 *
24	 * The refusal is all-or-nothing per import declaration. A declaration that names
25	 * ten symbols of which nine map is left exactly as it is, because a rewrite that
26	 * dropped the tenth would turn one honest diagnostic into a silent deletion.
27	 */
28	
29	import { compareStrings } from './angular-target-cell.ts';
30	import { applySourceEdits, lineOf, parseModule, type SourceEdit } from './semantic-module.ts';
31	
32	const CAPABILITY = 'Barrel entry point split';
33	
34	/** An exports-map subpath without its leading `./`. */
35	function stripDotSlash(subpath: string): string {
36		return subpath.startsWith('./') ? subpath.slice(2) : subpath;
37	}
38	
39	/** One published entry point of a package, as read from the installed closure. */
40	export type EntryPointSurface = Readonly<{
41		/** The exports-map subpath, `'.'` for the package root. */
42		subpath: string;
43		/** The specifier an importer writes to reach it. */
44		specifier: string;
45		/** Every name the entry point's declaration file exports. */
46		exports: readonly string[];
47		/**
48		 * Whether the declaration file re-exports a whole module (`export *`). A
49		 * surface with one of those is not fully enumerable from the file alone, so a
50		 * symbol is never mapped *into* it and the incompleteness is reported.
51		 */
52		opaque: boolean;
53	}>;
54	
55	/** A package's published entry points, as read from the installed closure. */
56	export type PackageSurfaceReading = Readonly<{
57		name: string;
58		version: string;
59		entryPoints: readonly EntryPointSurface[];
60	}>;
61	
62	export type BarrelSymbolResolution =
63		| Readonly<{ kind: 'root'; specifier: string }>
64		| Readonly<{ kind: 'entry-point'; specifier: string }>
65		| Readonly<{ kind: 'unmapped'; reason: string }>
66		| Readonly<{ kind: 'ambiguous'; reason: string }>;
67	
68	export type BarrelSplitChange = Readonly<{
69		kind: 'barrel-split';
70		line: number;
71		from: string;
72		to: string;
73		symbols: readonly string[];
74	}>;
75	
76	export type BarrelSplitMigration = Readonly<{
77		path: string;
78		source: string;
79		changed: boolean;
80		changes: readonly BarrelSplitChange[];
81		unhandled: readonly string[];
82	}>;
83	
84	/**
85	 * The names one entry point's declaration file exports.
86	 *
87	 * The declaration is parsed, not scanned: `export declare class X`,
88	 * `export { X }`, `export { X as Y }` and `export type X` all reach the same
89	 * record, and a name that only appears inside an import or a comment reaches
90	 * none of them. A declaration that does not parse is a hard failure naming the
91	 * entry point rather than an entry point silently read as exporting nothing.
92	 */
93	export function readEntryPointSurface(
94		packageName: string,
95		subpath: string,
96		declaration: string,
97	): EntryPointSurface {
98		const relative = subpath === '.' ? '' : `/${stripDotSlash(subpath)}`;
99		const specifier = `${packageName}${relative}`;
100		const module = parseModule(CAPABILITY, `${specifier}/index.d.ts`, declaration);
101		const exports: string[] = [];
102		let opaque = false;
103		for (const record of module.exports) {
104			if (record.isStar) {
105				opaque = true;
106				continue;
107			}
108			if (record.name === null || record.name === 'default') continue;
109			if (!exports.includes(record.name)) exports.push(record.name);
110		}
111		return Object.freeze({
112			subpath,
113			specifier,
114			exports: Object.freeze([...exports].sort(compareStrings)),
115			opaque,
116		});
117	}
118	
119	/** The depth of an exports-map subpath: `'.'` is 0, `'./button'` is 1. */
120	function depthOf(subpath: string): number {
121		return subpath === '.' ? 0 : stripDotSlash(subpath).split('/').length;
122	}
123	
124	/**
125	 * Where the installed package publishes `symbol`.
126	 *
127	 * The root entry point wins whenever it still exports the symbol: a barrel that
128	 * kept a name is not a barrel this capability splits. Otherwise the shallowest
129	 * entry point that exports it wins, and a tie at that depth is an ambiguity the
130	 * capability refuses rather than breaks — two entry points publishing the same
131	 * name are two different symbols as often as they are one.
132	 */
133	export function resolveBarrelSymbol(
134		reading: PackageSurfaceReading,
135		symbol: string,
136	): BarrelSymbolResolution {
137		const carriers = reading.entryPoints.filter(
138			(entry) => !entry.opaque && entry.exports.includes(symbol),
139		);
140		const root = carriers.find((entry) => entry.subpath === '.');
141		if (root !== undefined) return Object.freeze({ kind: 'root', specifier: root.specifier });
142		if (carriers.length === 0)
143			return Object.freeze({
144				kind: 'unmapped',
145				reason:
146					`${reading.name}@${reading.version} publishes no entry point that exports ` +
147					`${symbol}: the installed surface was read and the name is not on it`,
148			});
149		const shallowest = Math.min(...carriers.map((entry) => depthOf(entry.subpath)));
150		const best = carriers.filter((entry) => depthOf(entry.subpath) === shallowest);
151		const first = best[0];
152		if (first === undefined || best.length > 1)
153			return Object.freeze({
154				kind: 'ambiguous',
155				reason:
156					`${reading.name}@${reading.version} exports ${symbol} from ` +
157					`${best.map((entry) => entry.specifier).join(' and ')}, so which entry point owns it ` +
158					'is not a question the installed surface answers',
159			});
160		return Object.freeze({ kind: 'entry-point', specifier: first.specifier });
161	}
162	
163	type ImportedSpecifier = Readonly<{ name: string; text: string }>;
164	
165	/**
166	 * Split one module's imports of a package barrel into the entry points the
167	 * installed package publishes the named symbols from.
168	 *
169	 * Each rewritten declaration keeps its specifiers' own text — an alias, a
170	 * per-specifier `type` modifier — so the rewrite moves names between
171	 * declarations without restating what any of them said.
172	 */
173	export function splitBarrelImports(
174		path: string,
175		source: string,
176		reading: PackageSurfaceReading,
177	): BarrelSplitMigration {
178		const module = parseModule(CAPABILITY, path, source);
179		const edits: SourceEdit[] = [];
180		const changes: BarrelSplitChange[] = [];
181		const unhandled: string[] = [];
182		for (const declaration of module.ast.body) {
183			if (declaration.type !== 'ImportDeclaration') continue;
184			if (declaration.source.value !== reading.name) continue;
185			const line = lineOf(source, declaration.start);
186			const named: ImportedSpecifier[] = [];
187			let wide = false;
188			for (const specifier of declaration.specifiers) {
189				if (specifier.type !== 'ImportSpecifier' || specifier.imported.type !== 'Identifier') {
190					wide = true;
191					continue;
192				}
193				named.push({
194					name: specifier.imported.name,
195					text: source.slice(specifier.start, specifier.end),
196				});
197			}
198			if (wide) {
199				unhandled.push(
200					`${path} line ${String(line)}: the import of ${reading.name} carries a default or ` +
201						'namespace binding, whose members cannot be resolved to entry points by name, so the ' +
202						'declaration was left exactly as it is',
203				);
204				continue;
205			}
206			if (named.length === 0) continue;
207			const groups = new Map<string, ImportedSpecifier[]>();
208			const refusals: string[] = [];
209			let rootHeld = false;
210			for (const entry of named) {
211				const resolution = resolveBarrelSymbol(reading, entry.name);
212				if (resolution.kind === 'root') {
213					rootHeld = true;
214					continue;
215				}
216				if (resolution.kind !== 'entry-point') {
217					refusals.push(resolution.reason);
218					continue;
219				}
220				const group = groups.get(resolution.specifier);
221				if (group === undefined) groups.set(resolution.specifier, [entry]);
222				else group.push(entry);
223			}
224			if (refusals.length > 0) {
225				for (const reason of refusals)
226					unhandled.push(
227						`${path} line ${String(line)}: ${reason}. The whole declaration was left as it is: ` +
228							'splitting the symbols that do map would delete the one that does not.',
229					);
230				continue;
231			}
232			if (groups.size === 0) continue;
233			if (rootHeld) {
234				unhandled.push(
235					`${path} line ${String(line)}: ${reading.name}@${reading.version} still exports some of ` +
236						'the names this declaration imports from its root and publishes the others from ' +
237						'secondary entry points. A split that left a root import behind is a shape this ' +
238						'capability does not write, so the declaration was left as it is.',
239				);
240				continue;
241			}
242			const quote = source.slice(declaration.source.start, declaration.source.start + 1);
