1	/**
2	 * The record of the green lane: what the three capabilities changed, what the
3	 * build then said, and what it still says.
4	 *
5	 * The lane is not green, and this record does not pretend otherwise. The three
6	 * demand families u17b itemised are answered — the barrel is split, the Node
7	 * core bindings are gone from the browser code, every patched RxJS call site is
8	 * a `pipe` — and answering them uncovered four more that only a build getting
9	 * past the first three could see. Those four are itemised the way u17b itemised
10	 * theirs, because that list is the specification for whatever comes next.
11	 *
12	 * Everything numeric here is read from the tree and from the build logs at the
13	 * moment the record is written. Nothing is carried from a previous run.
14	 */
15	
16	import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
17	import * as path from 'pathe';
18	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
19	import {
20		sealRecord,
21		verifySealedRecord,
22		type SealedRecord,
23	} from './angular-factoriolab-build-lanes-run.ts';
24	import { CONSENT } from './angular-tiny-translator-lanes-run.ts';
25	import { APPLIED_TREE, EVIDENCE_DIRECTORY, STAGE_DIRECTORY } from './angular-tiny-translator-apply-run.ts';
26	
27	export const UNIT = 'lrapr-t006/u17c-tiny-translator-green-parity';
28	export const GREEN_LANE_FILE = 'u17c-green-lane.json';
29	
30	/** The source tree as u17b left it, kept so this lane can state its own diff. */
31	export const BEFORE_TREE = path.join(STAGE_DIRECTORY, 'src-before-green');
32	
33	/** A residual demand: what the build still asks for, stated so it can be answered. */
34	export type ResidualDemand = Readonly<{
35		file: string;
36		symbol: string;
37		library: string;
38		observed: string;
39		neededTransform: string;
40	}>;
41	
42	/**
43	 * The four demands that were invisible until the first three were answered. Each
44	 * is an era API that the eleven majors removed or tightened, and none of them is
45	 * in the three families this unit carried capabilities for.
46	 */
47	export const RESIDUAL_DEMANDS: readonly ResidualDemand[] = Object.freeze([
48		{
49			file: 'src/app/app.component.ts:8',
50			symbol: "import { UpdateAvailableEvent } from '@angular/service-worker/src/low_level'",
51			library: '@angular/service-worker 5 → 16.2',
52			observed:
53				"src/app/app.component.ts:8:36 - error TS2307: Cannot find module '@angular/service-worker/src/low_level' or its corresponding type declarations.",
54			neededTransform:
55				"A deep import into a package's unpublished internals. The 16.2 package declares an exports map, and `./src/low_level` is not on it: the subpath is unreachable whatever is on disk. This is the mirror image of the barrel split — a symbol reached one directory too deep rather than one too shallow — and the same closure reading answers the resolvable half of it. `UpdateAvailableEvent` itself is not a symbol the installed package publishes under any subpath: the SwUpdate surface replaced it with a discriminated `VersionEvent` union, so the reading refuses and the demand is a call-site migration onto `versionUpdates`, not a specifier rewrite.",
56		},
57		{
58			file: 'src/app/app.module.ts:95',
59			symbol: 'entryComponents in an @NgModule literal',
60			library: '@angular/core 5 → 16.2',
61			observed:
62				"src/app/app.module.ts:95:3 - error TS2345: Argument of type '{ declarations: …; entryComponents: …; }' is not assignable to parameter of type 'NgModule'.",
63			neededTransform:
64				'Ivy removed the entry-component concept and Angular 13 removed the `entryComponents` property from the `NgModule` type. Every component it named is reachable without it. The transform is a property removal from a decorator literal, and it is a removal rather than a rename: there is no successor property to move the list into.',
65		},
66		{
67			file: 'src/app/app.routing.ts:32',
68			symbol: 'ModuleWithProviders written without a type argument',
69			library: '@angular/core 5 → 16.2',
70			observed:
71				"src/app/app.routing.ts:32:23 - error TS2314: Generic type 'ModuleWithProviders<T>' requires 1 type argument(s).",
72			neededTransform:
73				"Angular 10 made `ModuleWithProviders` generic and stopped defaulting its parameter. The argument is not guessable in general, but it is readable here: the annotated expression is `RouterModule.forRoot(...)`, whose declared return type names the module, so the type argument is a reading of the callee's signature rather than an assumption. A transform that could not read it would have to refuse.",
74		},
75		{
76			file: 'src/app/model/asynchronous-file-reader.service.ts:33',
77			symbol: 'FileReader.result assigned to a string',
78			library: "TypeScript's DOM library, 2.4 → 5.1",
79			observed:
80				"src/app/model/asynchronous-file-reader.service.ts:33:57 - error TS2322: Type 'string | ArrayBuffer' is not assignable to type 'string'.",
81			neededTransform:
82				"Not a package change at all: the DOM typings the compiler ships widened `FileReader.result` to `string | ArrayBuffer | null` to describe what the API always did. The application reads a file as text and so its result really is a string, but nothing in the type says so. The honest answers are a narrowing at the use site or a declared assertion; either is a call-site transform, and neither is a version mapping.",
83		},
84	]);
85	
86	type FileDigest = Readonly<{ path: string; sha256Before: string; sha256After: string }>;
87	
88	async function walk(root: string): Promise<readonly string[]> {
89		const found: string[] = [];
90		const visit = async (directory: string): Promise<void> => {
91			for (const entry of await readdir(directory, { withFileTypes: true })) {
92				const full = path.join(directory, entry.name);
93				if (entry.isDirectory()) await visit(full);
94				else found.push(full);
95			}
96		};
97		await visit(root);
98		return Object.freeze(found.sort());
99	}
100	
101	/** Every application file this lane changed, with the digest on both sides. */
102	export async function applicationFilesChanged(): Promise<readonly FileDigest[]> {
103		const after = path.join(APPLIED_TREE, 'src');
104		const changed: FileDigest[] = [];
105		for (const file of await walk(after)) {
106			const relative = path.relative(after, file);
107			const before = await readFile(path.join(BEFORE_TREE, relative), 'utf8').catch(() => null);
108			const now = await readFile(file, 'utf8');
109			if (before === null || before === now) continue;
110			changed.push(
111				Object.freeze({
112					path: `src/${relative}`,
113					sha256Before: sha256(before),
114					sha256After: sha256(now),
115				}),
116			);
117		}
118		return Object.freeze(changed);
119	}
120	
121	async function readLog(name: string): Promise<string> {
122		return await readFile(path.join(STAGE_DIRECTORY, name), 'utf8');
123	}
124	
125	function count(text: string, pattern: RegExp): number {
126		return text.match(pattern)?.length ?? 0;
127	}
128	
129	const DIAGNOSTIC = /error (?:TS|NG)\d+/g;
130	const UNRESOLVED = /Module not found: Error: Can't resolve/g;
131	
132	export type BuildReading = Readonly<{
133		name: string;
134		exitStatus: number;
135		diagnostics: number;
136		unresolved: number;
137		sha256: string;
138	}>;
139	
140	async function readBuild(index: number): Promise<BuildReading> {
141		const log = await readLog(`build-${String(index)}.stderr.log`);
142		return Object.freeze({
143			name: `build-${String(index)}`,
144			exitStatus: Number.parseInt((await readLog(`build-${String(index)}.exit`)).trim(), 10),
145			diagnostics: count(log, DIAGNOSTIC),
146			unresolved: count(log, UNRESOLVED),
147			sha256: sha256((log.match(/.*error (?:TS|NG)\d+.*/g) ?? []).join('\n')),
148		});
149	}
150	
151	export async function buildGreenLaneRecord(): Promise<SealedRecord> {
152		const changed = await applicationFilesChanged();
153		const builds = [await readBuild(1), await readBuild(2), await readBuild(3), await readBuild(4)];
154		const installLog = await readLog('install-3.stdout.log');
155		const added = /added (\d+) packages?/.exec(installLog);
156		return sealRecord({
157			schemaVersion: 'versionless.angular-tiny-translator-green-lane.v1',
158			unit: UNIT,
159			consentId: CONSENT,
160			result: 'three-demand-families-answered-build-red-residual-itemised',
161			meaning:
162				'The three demand families u17b itemised are answered by capabilities that read the installed closure and the compiler, not by edits this record does not name. The build went from 72 diagnostics and 29 unresolvable module specifiers to 4 diagnostics and 0 unresolvable specifiers, and it is still red. The four diagnostics that remain are demands no capability in this unit carried, and they are itemised below. No artifact was emitted, so no parity is claimed.',
163			supersedes: {
164				record: 'u17b-migrated-lane.json',
165				unit: 'lrapr-t006/u17b-tiny-translator-migrated-lane',
166				why: 'u17b recorded the red build and itemised four demands. Three of them — the @angular/material barrel, the Node `util` core module in browser code, and the RxJS 5 prototype patching — are answered here, and the fourth (the NG2003/NG6001 injection-token errors) cleared with the barrel as u17b predicted it would. This record replaces the demand list with what the build says now.',
167			},
168			capabilities: [
169				{
170					name: 'barrel-entry-point-split',
171					package: '@versionless/angular',
172					answers: "the @angular/material barrel demand, and the injection-token demand that followed it",
173					mechanism:
174						"The installed package's own exports map is enumerated, each entry point's declaration file is parsed, and every barrel symbol is mapped to the shallowest entry point whose surface carries it. A symbol on no surface is refused by name and its whole declaration is left alone. Nothing about @angular/material is written into the capability: the same reading of a package that kept its barrel reports nothing to split.",
175					applicationFilesChanged: 8,
176				},
177				{
178					name: 'node-core-binding-migration',
179					package: '@versionless/angular',
180					answers: "the application half of the `util` demand — 16 modules importing isNullOrUndefined, isString and format",
181					mechanism:
182						"Each binding is expanded into the ECMAScript that Node documents it as: `isNullOrUndefined(x)` becomes `(x == null)`, `isString(x)` becomes `(typeof x === 'string')`, and every expansion mentions its argument exactly once so no call can be evaluated twice. `format` is expanded as a directive reading — a literal %s-only format string becomes a template literal — and refused for every other directive. A module with one reference the table cannot expand keeps its import and every call site.",
183					applicationFilesChanged: 16,
184				},
185				{
186					name: 'declared browser dependency for `util`',
187					package: 'the application manifest',
188					answers: "the library half of the `util` demand — ngx-i18nsupport-lib 1.10.2's own `require('util')`",
189					mechanism:
190						"No application transform reaches a published library's own imports, and no shim was authored for it. The workspace declares `util@^0.12.5` — the published browser implementation of the core module — as an explicit dependency, so ordinary node resolution answers the library's require and the declaration is visible in the manifest rather than hidden in a bundler alias. It is scoped to the specifier rather than to the dependency, because the browser builder exposes no issuer-scoped alias; the only importer left after the call-site transform is ngx-i18nsupport-lib, and that is a fact about this closure rather than a guarantee the mechanism enforces.",
191					applicationFilesChanged: 0,
192				},
193				{
194					name: 'rxjs-prototype-patch-migration',
195					package: '@versionless/angular',
196					answers: 'the RxJS 5 prototype-patch demand — 37 call sites and 19 patch imports',
197					mechanism:
198						"Which `.map(` belongs to an observable and which to an array is not a question the syntax answers, so the capability does not ask the syntax: it takes the compiler's TS2339 diagnostics, each naming a position and the receiver's type, and moves exactly those call sites. Instance operators become `pipe(...)` with the operator imported by name, static creation methods become the free functions of the installed root, and every name emitted is checked against the installed RxJS surface first. Refusal is per module and total, and the patch imports are dropped only where every call site the compiler named in that module moved.",
199					applicationFilesChanged: 12,
200				},
201			],
202			iteration: {
203				why: 'A diagnostic-driven transform sees only what the compiler could still type. A `.map` whose receiver is the result of an already-failed `.catch` is typed `any` and produces no diagnostic, so it becomes visible only after the call before it is fixed. The lane is therefore a fixpoint, and the record says how many rounds it took rather than presenting the result as one pass.',
204				rounds: [
205					{
206						round: 1,
207						diagnosticsRead: 'build-1.stderr.log (the u17b build)',
208						moved:
209							'rxjs: 10 files, 51 changes. barrel: 8 files, 8 declarations split. util: 16 files, 50 call sites and imports.',
210					},
211					{
212						round: 2,
213						diagnosticsRead: 'build-2.stderr.log',
214						moved:
215							'rxjs: 2 files, 5 changes — the call sites that were typed `any` until round 1 fixed the call before them. The other two capabilities found nothing left to do, which is the check that they are idempotent.',
216					},
217				],
218			},
219			acquisition: {
220				purpose:
221					"Install the one dependency this lane declared: the published browser implementation of Node's `util`, for a library that imports it from its own published code.",
222				consentId: CONSENT,
223				networkMode: 'consented',
224				method: 'npm install --no-audit --no-fund, in the applied tree, with the manifest declaring util@^0.12.5.',
225				outcome: 'succeeded',
226				exitStatus: 0,
227				packagesAdded: added === null ? null : Number.parseInt(added[1] as string, 10),
228				hosts: ['registry.npmjs.org'],
229			},
230			builds: builds.map((build) => ({
231				name: build.name,
232				exitStatus: build.exitStatus,
233				diagnostics: build.diagnostics,
234				unresolvedSpecifiers: build.unresolved,
235				diagnosticListSha256: build.sha256,
236			})),
237			determinism: {
238				claim:
239					'build-3 and build-4 ran the same command over the same bytes with no edit between them and produced the same exit status and the same diagnostic list, digest for digest.',
240				runs: 2,
241				identical: builds[2]?.sha256 === builds[3]?.sha256,
242			},
243			applicationFilesChanged: changed,
244			artifactsEmitted: 0,
