			.slice(start, site.end)
			.split('\n')
			.map((text) => (text.trim() === '' ? text : `${unit}${text}`))
			.join('\n');
		edits.push({
			start,
			end: site.end,
			text:
				`${prefix}if (typeof ${site.binding} === '${diagnostic.targetType}') {\n` +
				`${body}\n${prefix}}`,
		});
