		changes.push({
			kind: 'widened-union-narrowing',
			line: lineOf(source, site.start),
			binding: site.binding,
			sourceType: diagnostic.sourceType,
			targetType: diagnostic.targetType,
			statementsGuarded: site.region.length,
		});
